/** Result type inferred from a typed TDLib request. / Тип результата, выведенный из типизированного запроса TDLib. @public */
export type TdResultFor<T extends TdRequest> = T['@type'] extends keyof TdResultMap
  ? TdResultMap[T['@type']]
  : never;
